  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Determines whether a customer can book seats on a trip. The trip must exist, the trip must still have enough available seats, the requested seats must not exceed the remaining seats, and the customer must not already hold another booking whose trip time overlaps on the same day. The booking time must be strictly earlier than the departure time by more than two hours. When accepted, the trip seat count is reduced. Invalid inputs such as null customer, null trip, or null bookingDate return false.
   * Algorithm:
   *   1. If this.customer is null or this.trip is null or this.bookingDate is null, return false.
   *   2. If this.trip.bookSeats(this.numberOfSeats) returns false, return false.
   *   3. If this.numberOfSeats <= 0 or this.numberOfSeats > this.trip.numberOfSeats, return false.
   *   4. For each booking in this.customer.bookings:
   *        a. If booking.trip.isTimeConflicting(this.trip.departureTime, this.trip.arrivalTime) returns true, return false.
   *   5. Calculate time difference between this.trip.departureTime and current time. If difference is less than or equal to 2 hours, return false.
   *   6. Call this.updateTripSeats() to reduce seat count.
   *   7. Return true.
   * Related Features: customer, trip, bookingDate, numberOfSeats, trip.bookSeats, trip.numberOfSeats, trip.departureTime
   * Related Classes: Customer, Trip
   * Input: None (uses instance fields: customer, trip, bookingDate, numberOfSeats)
   * Output: boolean — true if booking is eligible
   * Pre-condition: Booking object is initialized with customer, trip, bookingDate, and numberOfSeats.
   * Post-condition: Returns eligibility and updates trip seats if accepted.
   * <!-- end-model-doc -->
   * @model kind="operation"
   *        annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean isBookingEligible()
  {
    // 1. If this.customer is null or this.trip is null or this.bookingDate is null, return false.
    if (getCustomer() == null || getTrip() == null || getBookingDate() == null) {
      return false;
    }
    
    // 2. If this.trip.bookSeats(this.numberOfSeats) returns false, return false.
    if (!getTrip().bookSeats(getNumberOfSeats())) {
      return false;
    }
    
    // 3. If this.numberOfSeats <= 0 or this.numberOfSeats > this.trip.numberOfSeats, return false.
    if (getNumberOfSeats() <= 0 || getNumberOfSeats() > getTrip().getNumberOfSeats()) {
      return false;
    }
    
    // 4. For each booking in this.customer.bookings:
    for (Booking booking : getCustomer().getBookings()) {
      // a. If booking.trip.isTimeConflicting(this.trip.departureTime, this.trip.arrivalTime) returns true, return false.
      if (booking.getTrip() != null && booking.getTrip().isTimeConflicting(getTrip().getDepartureTime(), getTrip().getArrivalTime())) {
        return false;
      }
    }
    
    // 5. Calculate time difference between this.trip.departureTime and current time.
    try {
      SimpleDateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd");
      SimpleDateFormat dateTimeFormat = new SimpleDateFormat("yyyy-MM-dd HH:mm");
      String dateStr = dateFormat.format(getTrip().getDepartureDate());
      Date fullDepDateTime = dateTimeFormat.parse(dateStr + " " + getTrip().getDepartureTime());
      long diffMillis = fullDepDateTime.getTime() - System.currentTimeMillis();
      if (diffMillis <= 0 || diffMillis <= 2 * 60 * 60 * 1000L) {
        return false;
      }
    } catch (ParseException e) {
      return false;
    }
    
    // 6. Call this.updateTripSeats() to reduce seat count.
    updateTripSeats();
    
    // 7. Return true.
    return true;
  }

